import{_ as o,c as a,a0 as i,o as l}from"./chunks/framework.B6JXc2q-.js";const h=JSON.parse('{"title":"WebUI 播放契约故障记录与方案 A 实施记录","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/webui_playback_contract_incident_and_repair_plan.md","filePath":"architecture/webui_playback_contract_incident_and_repair_plan.md"}'),d={name:"architecture/webui_playback_contract_incident_and_repair_plan.md"};function t(c,e,r,n,s,p){return l(),a("div",null,e[0]||(e[0]=[i(`<h1 id="webui-播放契约故障记录与方案-a-实施记录" tabindex="-1">WebUI 播放契约故障记录与方案 A 实施记录 <a class="header-anchor" href="#webui-播放契约故障记录与方案-a-实施记录" aria-label="Permalink to &quot;WebUI 播放契约故障记录与方案 A 实施记录&quot;">​</a></h1><blockquote><p>状态：<strong>已完成 / 测试服务器与设备实播验收通过</strong> 记录日期：2026-09-23 最后更新：2026-09-28 适用场景：修复主页“播放测试”和在线搜索播放，并建立最小前后端契约门禁 方案：Akari 已确认方案 A；Manager 已批准窄范围 <code>online_plugin</code> SourcePlugin 与进程内 TTL 引用存储。 当前结论：代码、CI、测试服务器契约、真实 WebUI 搜索入口与设备实播均已闭合；最终原始设备状态确认 <code>status=2</code>。</p></blockquote><hr><h2 id="实施记录-2026-09-24" tabindex="-1">实施记录（2026-09-24） <a class="header-anchor" href="#实施记录-2026-09-24" aria-label="Permalink to &quot;实施记录（2026-09-24）&quot;">​</a></h2><ul><li>已删除主页 <code>prefer_codec</code>、<code>search_key</code> 请求构造，新增 typed <code>PlayOptions</code> 与集中 builder。</li><li>已增加普通 / 代理链接 payload、在线 opaque 引用 payload、严格未知字段、真实 FastAPI router + exception handler 的回归测试；CI 增加 Python 定点测试、全部 WebUI 测试和 production build 门禁。</li><li>主页播放错误提示现在包含稳定 <code>error_code</code>、<code>stage</code>、<code>request_id</code>，且请求阶段明确显示“请求契约不匹配”。</li><li>已新增单一内置 <code>OnlinePluginSourcePlugin</code>。在线搜索仅为包含 <code>platform</code> 与稳定媒体身份的 raw item 创建高熵 <code>opq_</code> token；原始 item 只存进程内、有 TTL、有容量上限的并发安全存储，WebUI 只收到 token、<code>online_plugin</code>、media_id 和 title。</li><li>已验证在线插件通过现有 <code>OnlineMusicService.get_media_source_url()</code> 获取真实媒体流并构造 <code>ResolvedMedia</code>；不存在、过期和上游失败均返回脱敏稳定错误。</li><li>OpenAPI/Jellyfin 或缺少 <code>platform</code> / 稳定身份的结果不生成引用，搜索面板显示“暂无正式播放引用”并禁用确认；禁止标题回退。</li><li>共享 JSON fixture 作为 TS builder 与 Python router schema 的单一样本；README Roadmap 仍不恢复完成，因为未进行测试服务器/真实入口验收。</li><li>未增加 <code>online_plugin</code> delivery proxy fallback：当前 <code>DeliveryAdapter</code> 仅按 source 集合决定 fallback，虽将 <code>ResolvedMedia.headers</code> 带入 <code>PreparedStream</code>，Mina/relay 投递路径并未证明能以这些 headers 发起代理请求；猜测性加入 fallback 不能解决已证实问题，留待独立 delivery 设计。</li></ul><h2 id="实施与测试服务器验收记录-2026-09-28" tabindex="-1">实施与测试服务器验收记录（2026-09-28） <a class="header-anchor" href="#实施与测试服务器验收记录-2026-09-28" aria-label="Permalink to &quot;实施与测试服务器验收记录（2026-09-28）&quot;">​</a></h2><ul><li>修复 hardened 容器 <code>read_only</code> rootfs 下 JS plugin 搜索被 <code>EROFS</code> 阻断的问题：删除 runner 对原始搜索结果写入 <code>00-plugin_debug.log</code> 的行为及无其他用途的 <code>fs</code> 依赖；保留搜索校验、platform 补全、sandbox、网络和其他日志语义。</li><li>Node 回归测试使用内联离线 fixture，验证插件 load/search、platform 补全、只读风格工作目录以及不创建调试文件，并以源码断言防止敏感原始结果落盘回归；按发布 CI 的单测试文件挂载方式在只读容器中 <code>11/11</code> 通过。</li><li>部署前创建可回滚备份 <code>backups/smoke-backup-20260928_072637.tar.gz</code>，源码包本地与服务器 SHA-256 一致；测试容器重建后健康，内置 source 列表包含 <code>online_plugin</code>。</li><li>新 YouTube URL <code>jifImKwD1mw</code> 在测试服务器解析成功：<code>source_plugin=site_media</code>、<code>is_live=false</code>、取得音频流。旧 <code>prefer_codec</code> payload 返回结构化 HTTP 422；普通与代理新 payload 均通过 schema，并在假设备处返回预期 <code>E_DEVICE_NOT_FOUND</code>。</li><li>使用临时 MusicFree fixture plugin 验证真实 <code>search → opq_ token → online_plugin resolve</code> 链路：搜索响应不泄漏原始 URL，两次解析均成功，未知 token 返回 <code>E_RESOLVE_NONZERO_EXIT/resolve</code>。浏览器中的搜索结果、无引用标记、确认按钮禁用状态均符合设计。</li><li>临时插件已卸载，服务器恢复为无启用 JS plugin；日志中没有新的 <code>EROFS</code> 或 <code>00-plugin_debug.log</code> 错误。</li><li>容器重启后小米认证曾进入 <code>manual_login_required</code>，上游返回 70016；Akari 完成人工登录后运行时恢复 <code>healthy</code>，本工作包未修改 auth。</li><li>使用 <code>jifImKwD1mw</code> 完成真实设备验收：<code>POST /api/v1/play</code> 返回 <code>code=0</code>、<code>source_plugin=site_media</code>、<code>transport=mina</code>；播放中 probe 原始 <code>status=1</code>，权威状态为 <code>playing/is_playing=true</code>。随后 stop 成功，最终 probe 原始 <code>status=2</code>，权威状态为 <code>stopped/is_playing=false</code>，音量保持 27。</li></ul><h2 id="_1-问题" tabindex="-1">1. 问题 <a class="header-anchor" href="#_1-问题" aria-label="Permalink to &quot;1. 问题&quot;">​</a></h2><p>主页存在至少两条真实用户路径，其请求体与后端正式契约不一致。前端测试和后端测试分别通过，但组合后的生产请求在进入业务逻辑前返回 HTTP 422。</p><p>这不是 YouTube 解析器整体失效。测试服务器已成功解析普通 YouTube 视频和有效直播；本次主页问题发生在 API 请求校验阶段。</p><h3 id="_1-1-已证实故障" tabindex="-1">1.1 已证实故障 <a class="header-anchor" href="#_1-1-已证实故障" aria-label="Permalink to &quot;1.1 已证实故障&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用户路径</th><th>前端请求</th><th>后端契约</th><th>现场结果</th></tr></thead><tbody><tr><td>主页 → 测试 → 播放链接 / 代理播放</td><td><code>options.prefer_codec = &quot;auto&quot;</code></td><td><code>PlayOptionsModel(extra=&quot;forbid&quot;)</code> 中无 <code>prefer_codec</code></td><td>测试服务器 HTTP 422</td></tr><tr><td>主页 → 在线搜索 → 选择结果 → 确定</td><td><code>options.search_key = &lt;keyword&gt;</code></td><td><code>PlayOptionsModel(extra=&quot;forbid&quot;)</code> 中无 <code>search_key</code></td><td>测试服务器 HTTP 422</td></tr></tbody></table><p>代码位置：</p><ul><li><code>xiaomusic/webui/src/pages/HomePage.tsx</code><ul><li><code>playLink()</code> 发送 <code>prefer_codec</code></li><li><code>confirmSearch()</code> 发送 <code>search_key</code></li></ul></li><li><code>xiaomusic/webui/src/services/v1Api.ts</code><ul><li><code>PlayRequest.options</code> 当前为 <code>Record&lt;string, unknown&gt;</code>，TypeScript 无法发现非法字段</li></ul></li><li><code>xiaomusic/api/models/play_request.py</code><ul><li><code>PlayOptionsModel</code> 拒绝所有未声明字段</li></ul></li></ul><h3 id="_1-2-在线搜索播放还有第二层契约缺口" tabindex="-1">1.2 在线搜索播放还有第二层契约缺口 <a class="header-anchor" href="#_1-2-在线搜索播放还有第二层契约缺口" aria-label="Permalink to &quot;1.2 在线搜索播放还有第二层契约缺口&quot;">​</a></h3><p><code>GET /api/v1/search/online</code> 当前只向 WebUI 返回：</p><ul><li><code>name</code></li><li><code>title</code></li><li><code>artist</code></li></ul><p>它没有返回可稳定播放所需的来源身份，例如：</p><ul><li><code>source_hint</code></li><li>稳定 <code>media_id</code></li><li>来源插件标识</li><li>受约束的 <code>source_payload</code> 或其他正式播放引用</li></ul><p>因此，即使简单删除 <code>search_key</code> 使请求不再 422，主页仍只能拿标题调用 <code>/api/v1/play</code>，无法保证播放的是用户选中的在线搜索结果。只删除字段会把“明确失败”变成“请求被接受但语义不可靠”，不构成完整修复。</p><h3 id="_1-3-测试为何没有拦住" tabindex="-1">1.3 测试为何没有拦住 <a class="header-anchor" href="#_1-3-测试为何没有拦住" aria-label="Permalink to &quot;1.3 测试为何没有拦住&quot;">​</a></h3><ul><li>WebUI 测试 mock <code>v1Api.play()</code>，mock 不校验真实后端 schema。</li><li>后端测试证明“未知字段应被拒绝”，但没有将主页真实 payload 提交到完整 FastAPI app。</li><li>前端 <code>options?: Record&lt;string, unknown&gt;</code> 放弃了编译期字段约束。</li><li>当前发布 CI 只构建镜像、验证 Python import 和 Node 安全测试，不运行 Python 功能测试或 WebUI 测试。</li><li>发布记录仍保留 <code>106 failed</code> 的历史测试基线，整体测试结果存在较高噪声。</li></ul><h3 id="_1-4-与本次问题无关但需要区分的现场" tabindex="-1">1.4 与本次问题无关但需要区分的现场 <a class="header-anchor" href="#_1-4-与本次问题无关但需要区分的现场" aria-label="Permalink to &quot;1.4 与本次问题无关但需要区分的现场&quot;">​</a></h3><p>以下 URL：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://www.youtube.com/watch?v=28KRPhVzCus</span></span></code></pre></div><p>当前被 yt-dlp 判定为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This live stream recording is not available.</span></span></code></pre></div><p>这是特定上游直播 ID 已失效或录像不可用，不是主页 422 的根因，不纳入本次代码修复。</p><hr><h2 id="_2-根因" tabindex="-1">2. 根因 <a class="header-anchor" href="#_2-根因" aria-label="Permalink to &quot;2. 根因&quot;">​</a></h2><h3 id="_2-1-直接原因" tabindex="-1">2.1 直接原因 <a class="header-anchor" href="#_2-1-直接原因" aria-label="Permalink to &quot;2.1 直接原因&quot;">​</a></h3><p>2026-07-30 后端将 <code>options</code> 从任意字典收紧为 <code>PlayOptionsModel(extra=&quot;forbid&quot;)</code>，但没有迁移或验证所有 WebUI 消费者。主页从更早版本保留下来的 <code>prefer_codec</code> 与 <code>search_key</code> 因而成为非法字段。</p><h3 id="_2-2-系统性原因" tabindex="-1">2.2 系统性原因 <a class="header-anchor" href="#_2-2-系统性原因" aria-label="Permalink to &quot;2.2 系统性原因&quot;">​</a></h3><ol><li>API、Core 和 WebUI 各自维护播放参数结构，没有单一可执行契约。</li><li>模块已拆分，消费者同步和跨层测试没有同步建立。</li><li>功能测试偏向局部 mock，没有覆盖真实用户入口到生产 app 的组合路径。</li><li>变更批次长期过宽，契约收紧、路径治理、状态重构和发布工作互相夹带。</li><li>CI 与验收没有形成足够硬的发布阻断条件。</li></ol><h3 id="_2-3-架构判断" tabindex="-1">2.3 架构判断 <a class="header-anchor" href="#_2-3-架构判断" aria-label="Permalink to &quot;2.3 架构判断&quot;">​</a></h3><p>统一播放入口、严格 schema、Source/Transport 分层和权威状态源等方向不应回滚。需要修正的是边界契约的执行方式和验收方式。</p><hr><h2 id="_3-roadmap-对照与范围筛选" tabindex="-1">3. Roadmap 对照与范围筛选 <a class="header-anchor" href="#_3-roadmap-对照与范围筛选" aria-label="Permalink to &quot;3. Roadmap 对照与范围筛选&quot;">​</a></h2><p>Roadmap 权威入口：<code>README.md</code> 第 5 节。</p><table tabindex="0"><thead><tr><th>Roadmap 项</th><th>与本次关系</th><th>本计划处理方式</th></tr></thead><tbody><tr><td>WebUI 主流程围绕 v1 正式控制面持续收敛（当前标记完成）</td><td>两条主页真实路径仍违反 v1 契约，完成状态需要重新核验</td><td><strong>纳入本次</strong>：修复并通过真实契约验收后，再确认该项是否仍可标记完成</td></tr><tr><td>核心能力与来源扩展边界继续收敛</td><td>在线搜索结果缺少正式播放引用，属于来源边界渗漏</td><td><strong>仅纳入窄切片</strong>：定义“搜索结果 → 播放请求”所需的最小正式契约；不重构整个 Source/Runtime</td></tr><tr><td>来源能力整理为更清晰的插件范式</td><td>搜索结果应携带来源身份，但插件体系整体治理范围过大</td><td><strong>只记录后续</strong>：本次仅补可播放引用，不做插件管理器或能力声明大改</td></tr><tr><td>播放稳定性与认证恢复可观测性继续加强</td><td>主页失败提示缺少足够的请求关联信息；SourceResolveError 过度压缩上游原因</td><td><strong>纳入最小可观测性</strong>：失败提示保留 <code>request_id</code>、阶段和稳定错误码；不改认证状态机，不直接暴露 yt-dlp 原始 stderr</td></tr><tr><td>自托管部署体验与安全默认配置持续打磨</td><td>与当前 WebUI 播放契约没有共享修改面</td><td><strong>明确排除</strong></td></tr></tbody></table><p>其他历史跟进项：</p><ul><li><code>disabled_plugins</code> 持久化：排除。</li><li>auth P2（并发、TTL、87001/70016 分类等）：排除，另立工作包。</li><li>全量插件范式和 Source/Runtime 防腐层整改：排除，另立工作包。</li><li><code>play_id/session_id</code> 全链路：排除；本次只利用现有 <code>request_id</code>。</li></ul><hr><h2 id="_4-方案-a-实施计划" tabindex="-1">4. 方案 A 实施计划 <a class="header-anchor" href="#_4-方案-a-实施计划" aria-label="Permalink to &quot;4. 方案 A 实施计划&quot;">​</a></h2><h3 id="步骤-0-冻结边界" tabindex="-1">步骤 0：冻结边界 <a class="header-anchor" href="#步骤-0-冻结边界" aria-label="Permalink to &quot;步骤 0：冻结边界&quot;">​</a></h3><p>在 Akari 确认前：</p><ul><li>不修改业务代码；</li><li>不构建候选镜像；</li><li>不部署测试服务器；</li><li>不顺手修改 auth、relay、transport、设备状态机或插件管理。</li></ul><h3 id="步骤-1-先建立失败测试" tabindex="-1">步骤 1：先建立失败测试 <a class="header-anchor" href="#步骤-1-先建立失败测试" aria-label="Permalink to &quot;步骤 1：先建立失败测试&quot;">​</a></h3><p>新增对旧代码必失败的测试，至少覆盖：</p><ol><li><code>playLink(false)</code> 生成的真实请求体能被 <code>PlayRequest</code> 接受；</li><li><code>playLink(true)</code> 的 <code>prefer_proxy=true</code> 请求能被接受；</li><li><code>confirmSearch()</code> 不再发送未声明字段；</li><li>在线搜索结果包含足够信息，可构造确定的正式播放请求；</li><li>未声明 options 字段仍应返回结构化 HTTP 422，不能为了兼容旧前端而放宽 <code>extra=&quot;forbid&quot;</code>。</li></ol><blockquote><p>注意：不得把后端改回任意字典，也不得只修改 mock 使测试变绿。</p></blockquote><h3 id="步骤-2-恢复主页播放测试" tabindex="-1">步骤 2：恢复主页播放测试 <a class="header-anchor" href="#步骤-2-恢复主页播放测试" aria-label="Permalink to &quot;步骤 2：恢复主页播放测试&quot;">​</a></h3><p>建议的最小实现：</p><ol><li>删除无实现依据的 <code>prefer_codec</code>；</li><li>在前端声明与后端一致的 <code>PlayOptions</code> 类型，替换 <code>Record&lt;string, unknown&gt;</code>；</li><li>将主页请求构造从 <code>HomePage.tsx</code> 抽到可单测的 typed builder/service；</li><li>保留 <code>no_cache</code>、<code>prefer_proxy</code> 等正式字段；</li><li>普通链接、移动端 YouTube 链接及带 Mix 参数的链接均继续由 <code>source_hint=&quot;auto&quot;</code> 进入统一播放入口。</li></ol><h3 id="步骤-3-闭合在线搜索到播放的正式契约" tabindex="-1">步骤 3：闭合在线搜索到播放的正式契约 <a class="header-anchor" href="#步骤-3-闭合在线搜索到播放的正式契约" aria-label="Permalink to &quot;步骤 3：闭合在线搜索到播放的正式契约&quot;">​</a></h3><p>实际实现：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MusicFree raw item（platform + 稳定身份）</span></span>
<span class="line"><span>  → OnlinePluginReferenceStore.put() → 高熵 opq_ token</span></span>
<span class="line"><span>  → WebUI: query + source_hint=online_plugin + media_id/title</span></span>
<span class="line"><span>  → POST /api/v1/play</span></span>
<span class="line"><span>  → OnlinePluginSourcePlugin.get(token)</span></span>
<span class="line"><span>  → OnlineMusicService.get_media_source_url(raw item)</span></span>
<span class="line"><span>  → ResolvedMedia</span></span></code></pre></div><p>约束：</p><ul><li>WebUI 不接收 raw item、媒体 URL、cookie、token、source_payload 或 context_hint。</li><li>token 只在进程内存中存在，TTL、容量上限、并发安全；在同一 TTL 内允许播放链路安全重试。</li><li>只有服务端判定具备 <code>platform</code>、稳定身份且属于当前启用 MusicFree JS plugin 集合的结果生成引用；<code>OpenAPI-*</code>、<code>Jellyfin</code> 和未知 platform 明确不可播放。</li><li>不信任上游 raw item 的 <code>play_reference</code>，也不允许标题、搜索词回退。</li></ul><h3 id="步骤-4-补最小可观测性" tabindex="-1">步骤 4：补最小可观测性 <a class="header-anchor" href="#步骤-4-补最小可观测性" aria-label="Permalink to &quot;步骤 4：补最小可观测性&quot;">​</a></h3><p>同一修复包内仅做以下窄改动：</p><ul><li>主页失败提示显示稳定 <code>error_code</code>、<code>stage</code> 和 <code>request_id</code>；</li><li>HTTP 422 明确提示“请求契约不匹配”，避免误判为媒体解析失败；</li><li>Source 解析失败继续返回脱敏稳定错误码，不把完整媒体 URL、cookie、token 或 yt-dlp stderr 暴露给 WebUI。</li></ul><p>不在本次实现：</p><ul><li>新增完整 <code>play_id/session_id</code> 追踪体系；</li><li>重写 resolver 错误体系；</li><li>记录 ffmpeg 全量 stderr；</li><li>修改认证诊断。</li></ul><h3 id="步骤-5-加入发布门禁" tabindex="-1">步骤 5：加入发布门禁 <a class="header-anchor" href="#步骤-5-加入发布门禁" aria-label="Permalink to &quot;步骤 5：加入发布门禁&quot;">​</a></h3><p>最小门禁：</p><ol><li>WebUI 对主页“播放链接”“代理播放”“在线搜索后播放”三条路径做 payload 断言；</li><li>将这些真实 payload 提交到完整 FastAPI app，证明不会因 schema 返回 422；</li><li>后端严格字段测试继续存在；</li><li>WebUI production build 通过；</li><li>CI 至少运行本次相关 Python 测试、WebUI 测试与 build，而不是只验证 import；</li><li>全量测试结果单独记录，本次不得新增失败。</li></ol><p>历史 <code>106 failed</code> 不要求在本修复包内一次清零，但必须另建分域台账；不能继续以一个总数字长期豁免。</p><h3 id="步骤-6-测试服务器与用户入口验收" tabindex="-1">步骤 6：测试服务器与用户入口验收 <a class="header-anchor" href="#步骤-6-测试服务器与用户入口验收" aria-label="Permalink to &quot;步骤 6：测试服务器与用户入口验收&quot;">​</a></h3><h4 id="无声、无设备风险的契约验收" tabindex="-1">无声、无设备风险的契约验收 <a class="header-anchor" href="#无声、无设备风险的契约验收" aria-label="Permalink to &quot;无声、无设备风险的契约验收&quot;">​</a></h4><ul><li>使用不存在的测试 device ID 提交主页真实 payload；</li><li>预期进入业务层并返回 <code>E_DEVICE_NOT_FOUND</code>，而非 HTTP 422；</li><li>普通 YouTube 移动端链接通过 <code>/api/v1/resolve</code>；</li><li>无效直播 ID 返回 Source resolve 类错误，不能被误报为请求契约错误。</li></ul><h4 id="实机验收" tabindex="-1">实机验收 <a class="header-anchor" href="#实机验收" aria-label="Permalink to &quot;实机验收&quot;">​</a></h4><p>只在满足安全条件时执行：</p><ul><li>夜间或 Akari 睡觉期间，物理音量必须设置并回读为 0；否则立即 stop，不播放；</li><li>当前 OH2P 的物理最低回读为 4，因此夜间实机播放验收默认阻断；</li><li>日间验收或 Akari 另行明确授权后，按当时确认的安全音量执行；</li><li>验收结束必须 stop，并主动 probe 确认原始设备 <code>status=2</code>。</li></ul><p>用户入口至少覆盖：</p><ol><li>主页“播放链接”；</li><li>主页“代理播放”；</li><li>在线搜索、选择结果并播放；</li><li>失败信息包含可关联的 request_id；</li><li>stop 后无复播。</li></ol><h3 id="步骤-7-roadmap-与文档收口" tabindex="-1">步骤 7：Roadmap 与文档收口 <a class="header-anchor" href="#步骤-7-roadmap-与文档收口" aria-label="Permalink to &quot;步骤 7：Roadmap 与文档收口&quot;">​</a></h3><p>已完成代码级文档收口：</p><ul><li>API spec 描述 <code>online_plugin</code>、opaque token、TTL 存储与脱敏边界；</li><li>WebUI 架构文档描述 typed options、builder 和不可播放结果行为；</li><li>ADR-0006 已在实现与定点验证通过后改为 Accepted；</li><li>README Roadmap 在设备实播、最终 stop 与原始 <code>status=2</code> 验收通过后恢复完成；</li><li>发布说明不得把代码级测试扩大成服务器或实机稳定性结论。</li></ul><hr><h2 id="_5-验收标准" tabindex="-1">5. 验收标准 <a class="header-anchor" href="#_5-验收标准" aria-label="Permalink to &quot;5. 验收标准&quot;">​</a></h2><p>全部满足后才能判定修复完成：</p><ul><li>[x] <code>prefer_codec</code> 不再出现在主页正式播放请求中；</li><li>[x] <code>search_key</code> 不再作为未声明 options 字段发送；</li><li>[x] <code>PlayRequest.options</code> 在前端为明确类型，不再是 <code>Record&lt;string, unknown&gt;</code>；</li><li>[x] 播放测试和在线搜索播放均有对旧代码必失败的回归测试；</li><li>[x] 前端真实 payload 通过真实 FastAPI router 与 exception handler 校验；</li><li>[x] 未声明字段仍被严格拒绝；</li><li>[x] 在线搜索结果具有确定、正式、可测试的 opaque token 播放语义；</li><li>[x] 失败提示包含稳定错误码、阶段和 request_id；</li><li>[x] WebUI 测试、build 与相关 Python 测试进入 CI 门禁；</li><li>[x] 测试服务器契约与真实 WebUI 搜索入口验收通过；</li><li>[x] 实机播放成功，完成 stop 且 probe 原始 <code>status=2</code>；</li><li>[x] 没有夹带 auth、relay、transport、部署安全或插件体系重构；</li><li>[x] API/WebUI/ADR 与 README Roadmap 的当前状态按真实实现和阻断同步更新。</li></ul><hr><h2 id="_6-风险与回滚" tabindex="-1">6. 风险与回滚 <a class="header-anchor" href="#_6-风险与回滚" aria-label="Permalink to &quot;6. 风险与回滚&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>控制方式</th></tr></thead><tbody><tr><td>简单删除 <code>search_key</code> 后选中结果仍无法确定播放</td><td>将搜索结果播放引用作为本次必要契约，不以“请求不再 422”冒充完成</td></tr><tr><td>为兼容旧前端而放宽后端 schema</td><td>明确禁止；保留 <code>extra=&quot;forbid&quot;</code></td></tr><tr><td>借机重构插件体系或播放运行时</td><td>通过“不做事项”和变更文件白名单约束</td></tr><tr><td>测试再次只覆盖 mock</td><td>强制真实 payload → 完整 FastAPI app 契约测试</td></tr><tr><td>实机验收产生声音</td><td>遵守音量回读与 stop/status=2 安全规则</td></tr><tr><td>新 CI 被历史失败淹没</td><td>先设置本次定向硬门禁，历史失败另建分域台账，不混为一项</td></tr><tr><td>hardened rootfs 阻断 JS plugin 搜索并可能泄漏原始 URL/token</td><td>禁止原始搜索结果文件落盘；runner 在只读风格工作目录下由离线 fixture 回归测试验证</td></tr></tbody></table><p>回滚原则：</p><ul><li>修复采用独立、可回退提交；</li><li>部署前保留当前 v1.1.7 镜像与源码坐标；</li><li>WebUI 与后端必须来自同一候选提交，禁止散件覆盖；</li><li>任一入口验收失败即回滚整个候选，不在服务器上追补文件。</li></ul><hr><h2 id="_7-批准结论与剩余验收" tabindex="-1">7. 批准结论与剩余验收 <a class="header-anchor" href="#_7-批准结论与剩余验收" aria-label="Permalink to &quot;7. 批准结论与剩余验收&quot;">​</a></h2><p>Manager 已批准方案 A 的窄实现：新增一个内置 <code>online_plugin</code> SourcePlugin 与进程内 TTL opaque 引用存储，不扩展通用插件框架。</p><p>代码级契约、脱敏、引用存储、SourcePlugin、共享 fixture、WebUI、production build、容器 Node 门禁、测试服务器契约、真实 WebUI 搜索入口与设备实播均已通过。最终 stop 后主动 probe 确认原始 <code>status=2</code>；方案 A 验收闭合，README Roadmap 恢复完成。</p>`,92)]))}const b=o(d,[["render",t]]);export{h as __pageData,b as default};
